package csvcloud

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strings"
	"testing"

	tabular "pdfservice/internal/csvtabular"
	"pdfservice/internal/csvwire"
)

// Synthetic data is generated by offset, never stored as a whole file. Each row
// has a unique hash in its unchanged column, so the result is not just repeated
// padding compressed below the old encoded limit. The expected output is built
// directly from planted values, without calling the transform implementation.
type privateLargeReader struct {
	offset, end int64
	expected    bool
}

func (r *privateLargeReader) Read(p []byte) (int, error) {
	if r.offset >= r.end {
		return 0, io.EOF
	}
	if int64(len(p)) > r.end-r.offset {
		p = p[:r.end-r.offset]
	}
	total := 0
	header := "id,value,other\n"
	for len(p) > 0 {
		var row string
		var at int64
		if r.offset < int64(len(header)) {
			row = header
			at = r.offset
		} else {
			position := r.offset - int64(len(header))
			index := position / 1024
			at = position % 1024
			h := sha256.Sum256([]byte(fmt.Sprintf("utils-csv-synthetic-row-%d", index)))
			filler := strings.Repeat(hex.EncodeToString(h[:]), 16)[:1011]
			if index == (1<<20)-1 {
				filler = filler[:len(filler)-len(header)]
			}
			value := "old"
			if r.expected {
				value = "new"
			}
			row = fmt.Sprintf("%07d,%s,%s\n", index, value, filler)
		}
		n := copy(p, row[at:])
		if n == 0 {
			return total, ErrIntegrity
		}
		r.offset += int64(n)
		total += n
		p = p[n:]
	}
	return total, nil
}
func privateLargeTransformFixture() (privateHTTPFixtureData, error) {
	const size int64 = 1 << 30
	options, e := tabular.CanonicalOptions("transform", json.RawMessage(`{"column":"value","op":"replace","old":"old","new":"new"}`))
	if e != nil {
		return privateHTTPFixtureData{}, e
	}
	full := sha256.New()
	parts := []Part{}
	for i := 0; i < 16; i++ {
		part := sha256.New()
		r := &privateLargeReader{offset: int64(i) * (64 << 20), end: int64(i+1) * (64 << 20)}
		n, e := io.Copy(io.MultiWriter(full, part), r)
		if e != nil || n != 64<<20 {
			return privateHTTPFixtureData{}, ErrIntegrity
		}
		parts = append(parts, Part{Number: int32(i + 1), Bytes: n, SHA256: hex.EncodeToString(part.Sum(nil))})
	}
	expected := sha256.New()
	n, e := io.Copy(expected, &privateLargeReader{end: size, expected: true})
	if e != nil || n != size {
		return privateHTTPFixtureData{}, ErrIntegrity
	}
	q := csvwire.Request{Version: 2, Operation: "transform", Options: options, Files: []csvwire.File{{Slot: "file", Bytes: size, SHA256: hex.EncodeToString(full.Sum(nil))}}}
	return privateHTTPFixtureData{Request: q, Rows: 1 << 20, Parts: map[string][]Part{"file": parts}, ExpectedBytes: size, ExpectedSHA: hex.EncodeToString(expected.Sum(nil)), Open: func(slot string, offset, n int64) (io.ReadCloser, error) {
		if slot != "file" || offset < 0 || n <= 0 || offset+n > size {
			return nil, ErrInvalid
		}
		return io.NopCloser(&privateLargeReader{offset: offset, end: offset + n}), nil
	}}, nil
}
func TestPrivateFixtureMetadata(t *testing.T) {
	op := os.Getenv("CSV_PRIVATE_PRINT_FIXTURE")
	if op == "" {
		t.Skip("explicit metadata-only fixture generation")
	}
	f, e := privateSmallFixture(op)
	if op == "transform-large" {
		f, e = privateLargeTransformFixture()
	}
	if e != nil {
		t.Fatal(e)
	}
	raw, e := json.Marshal(struct {
		Request       csvwire.Request
		Parts         map[string][]Part
		ExpectedBytes int64
		ExpectedSHA   string
		Rows          int64
	}{f.Request, f.Parts, f.logicalBytes(), f.logicalSHA(), f.Rows})
	if e != nil {
		t.Fatal(e)
	}
	t.Logf("PRIVATE_FIXTURE_METADATA %s", raw)
}
